'use strict';
// Base, almacenamiento, navegación, eventos y herramientas.
'use strict';
const KEY='faro_estudio_v1';
const VIEWS=[['home','Inicio','home'],['security','Temario','book-open'],['practice','Tarjetas','layers'],['questions','Preguntas','brain'],['pbq','Práctica PBQ','shield'],['material','Apuntes','file-text'],['progress','Progreso','chart']];
const IC={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>','book-open':'<path d="M12 7v14M3 18V4a1 1 0 0 1 1-1h5a3 3 0 0 1 3 3v15a3 3 0 0 0-3-3H4a1 1 0 0 1-1-1ZM21 18V4a1 1 0 0 0-1-1h-5a3 3 0 0 0-3 3v15a3 3 0 0 1 3-3h5a1 1 0 0 0 1-1Z"/>','file-text':'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h8"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',brain:'<path d="M12 18V5a3 3 0 0 0-5.9-.8A4 4 0 0 0 5 11a4 4 0 0 0 1.2 7.6A3 3 0 0 0 12 18Zm0 0V5a3 3 0 0 1 5.9-.8A4 4 0 0 1 19 11a4 4 0 0 1-1.2 7.6A3 3 0 0 1 12 18Z"/>',chart:'<path d="M3 3v18h18M7 17v-4M12 17V8M17 17v-7"/>',plus:'<path d="M12 5v14M5 12h14"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>',layers:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 9v12"/>',flame:'<path d="M12 22c4 0 7-3 7-7 0-3-2-5-3-7-.6 3-2 4-3 4 0-4-1-6-4-10-.2 4-4 6-4 12 0 4 3 8 7 8z"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10H3z"/>',trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6M10 10v7M14 10v7"/>',edit:'<path d="m4 16 11-11 4 4L8 20H4zM13 7l4 4"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',star:'<path d="m12 2 3 7 7 .6-5.4 4.8 1.7 7-6.3-3.7-6.3 3.7 1.7-7L2 9.6 9 9z"/>',play:'<path d="m8 5 11 7-11 7z"/>',pause:'<path d="M8 5v14M16 5v14"/>',refresh:'<path d="M3 11a9 9 0 0 1 15-6l3 3M21 3v5h-5M21 13a9 9 0 0 1-15 6l-3-3M3 21v-5h5"/>'};
function icon(name){return `<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${IC[name]||IC.star}</svg>`}
function id(){return (crypto?.randomUUID?.()||'i'+Math.random().toString(36).slice(2))}
function blank(){return {version:1,subjects:[],topics:[],materials:[],cards:[],tasks:[],sessions:[],history:[],settings:{dailyGoal:45}}}
function load(){try{let s=JSON.parse(localStorage.getItem(KEY));if(s&&Array.isArray(s.subjects)&&Array.isArray(s.topics)&&Array.isArray(s.cards)){return {...blank(),...s,settings:{...blank().settings,...s.settings}}}}catch(e){}return blank()}
let db=load(),view='home',activeSubject=null,activeTopic=null,reviewFilter='all',quizFilter='all',practiceMode='repaso',reviewFlipped=false,quiz=null,focus={running:false,seconds:25*60,initial:25*60,topicId:'',timer:null},noteSaveTimer=null,toastTimer=null,query='';
function esc(v){return String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}
function today(){let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function shiftDay(date,n){let d=new Date((date||today())+'T12:00:00');d.setDate(d.getDate()+n);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function days(date){if(!date)return null;return Math.round((new Date(date+'T12:00:00')-new Date(today()+'T12:00:00'))/86400000)}
function niceDate(date){if(!date)return 'Sin fecha';try{return new Date(date+'T12:00:00').toLocaleDateString('es-ES',{day:'numeric',month:'short',year:'numeric'})}catch(e){return date}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch(e){toast('No se pudo guardar. El almacenamiento del navegador podría estar lleno. Exporta una copia.',true);return false}}
function toast(msg,err){const t=document.getElementById('toast');t.textContent=msg;t.style.background=err?'#9d4b58':'#262d4c';t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3800)}
const subject=id=>db.subjects.find(x=>x.id===id),topic=id=>db.topics.find(x=>x.id===id), topicSubject=tid=>subject(topic(tid)?.subjectId);
const allTopicCards=(tid)=>db.cards.filter(c=>c.topicId===tid), topicsFor=sid=>db.topics.filter(t=>t.subjectId===sid);
function pct(sid){let ts=topicsFor(sid);return ts.length?Math.round(100*ts.filter(t=>t.status==='done').length/ts.length):0}
function dueCards(){return db.cards.filter(c=>!c.due||c.due<=today())}
function nearest(){return db.subjects.filter(s=>s.examDate&&days(s.examDate)>=0).sort((a,b)=>a.examDate.localeCompare(b.examDate))[0]}
function candidateSubjects(){return db.subjects.filter(s=>!query||s.name.toLowerCase().includes(query.toLowerCase())||topicsFor(s.id).some(t=>t.name.toLowerCase().includes(query.toLowerCase())))}
function empty(emoji,title,copy,btn,action){return `<div class="empty"><div class="emoji">${emoji}</div><h3>${title}</h3><p>${copy}</p>${btn?`<button class="button soft" data-action="${action}">${icon('plus')} ${btn}</button>`:''}</div>`}
function goto(v){view=v;quiz=null;reviewFlipped=false;render();window.scrollTo({top:0,behavior:'smooth'})}
function render(){
 const root=document.getElementById('root');
 const names={route:'Ruta guiada',home:'Inicio',security:'Temario',practice:'Tarjetas',questions:'Preguntas',pbq:'Práctica PBQ',material:'Mis apuntes',progress:'Mi progreso'};
 const nav=VIEWS.map(([k,n,i])=>`<button class="${view===k?'active':''}" data-nav="${k}">${icon(i)}<span>${n}</span></button>`).join('');
 root.innerHTML=`<div class="page"><aside class="sidebar"><div class="logo"><div class="logo-mark">✦</div><div>faro<small>SECURITY+</small></div></div><div class="nav-label">Estudia a tu ritmo</div><div class="nav">${nav}</div><div class="side-bottom"><div class="quote">Sin horarios, sin presión.<br>Aprende, practica y repasa cuando quieras.</div><button class="side-btn" data-action="settings">${icon('settings')} Ajustes y copias</button></div></aside><main class="main"><header class="topbar"><div><span class="brand-mobile">✦ faro</span><span class="breadcrumb">SECURITY+ / ${esc(names[view]||'Estudiar')}</span></div><div class="top-right"><span class="pill gray">SY0-701</span><button class="button tiny ghost" data-action="settings" title="Copias de seguridad">${icon('settings')}</button></div></header><div id="content">${views[view]()}</div></main></div><nav class="mobile-nav">${VIEWS.map(([k,n,i])=>`<button data-nav="${k}" class="${view===k?'active':''}">${icon(i)}<span>${n==='Práctica PBQ'?'PBQ':n==='Mis apuntes'?'Apuntes':n==='Mi progreso'?'Progreso':n}</span></button>`).join('')}</nav>`;
}

const views={home:renderHome,subjects:renderSubjects,material:renderMaterial,plan:renderPlan,practice:renderPractice,progress:renderProgress};
function stat(n,label,ico,cl){return `<div class="stat"><div class="top"><span class="stat-icon ${cl||''}">${icon(ico)}</span></div><div class="n">${n}</div><div class="label">${label}</div></div>`}
function renderHome(){let s=db.subjects.length,t=db.topics.length,done=db.topics.filter(x=>x.status==='done').length,near=nearest(),tasks=db.tasks.filter(x=>!x.done).sort((a,b)=>(a.due||'9').localeCompare(b.due||'9'));return `<div class="section-row"><div><h1>¡Vamos a por ese examen! ✨</h1><p>Organiza lo que aprendes, repasa y avanza a tu ritmo.</p></div><button class="button ghost" data-action="settings">${icon('settings')} Ajustes</button></div><section class="hero"><div class="hero-copy"><div class="eyebrow">TU RUTA DE APRENDIZAJE</div><h2>${near?`Tu próximo examen: ${esc(near.name)} en ${days(near.examDate)===0?'¡hoy!':`${days(near.examDate)} ${days(near.examDate)===1?'día':'días'}`}`:'Aprende con un plan, no con improvisación.'}</h2><p>${near?`Fecha: ${niceDate(near.examDate)}. Dedica tiempo a tus temas pendientes y practica antes de la prueba.`:'Reúne tus apuntes, divide tus asignaturas en temas y prepara simulacros basados en tus tarjetas.'}</p><button class="button light" data-nav="${s?'practice':'subjects'}">${s?'Empezar a practicar':'Crear mi primera asignatura'} ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true">📚</div></section><div class="stats">${stat(s,'Asignaturas', 'book-open')}${stat(`${done}/${t}`,'Temas completados','check','green')}${stat(dueCards().length,'Tarjetas para repasar','layers','orange')}${stat(db.sessions.reduce((a,x)=>a+x.minutes,0),'Minutos estudiados','clock','pink')}</div><div class="grid2"><div><section class="panel"><div class="panel-head"><h3>Mis asignaturas</h3><button class="link-btn" data-nav="subjects">Ver todas ${icon('arrow')}</button></div>${!s?empty('📖','Empieza por una asignatura','Crea tus materias, añade sus temáticas y fija una fecha de examen.','Crear asignatura','add-subject'):`<div class="subject-grid">${db.subjects.slice(0,4).map(renderSubjectCard).join('')}</div>`}</section><section class="panel" style="margin-top:20px"><div class="panel-head"><h3>Actividad reciente</h3><button class="link-btn" data-nav="progress">Ver progreso ${icon('arrow')}</button></div>${db.sessions.length||db.history.length?renderActivity():empty('📈','Tu progreso empieza aquí','Las sesiones de concentración y los resultados de los simulacros aparecerán aquí.')}</section></div><div><section class="panel"><div class="panel-head"><h3>Para hoy</h3><button class="link-btn" data-nav="plan">Ver plan ${icon('arrow')}</button></div>${tasks.length?tasks.slice(0,5).map(renderTaskRow).join(''):`<div class="empty"><div class="emoji">✅</div><h3>Sin tareas pendientes</h3><p>Crea tareas en tu planificador para tener una guía diaria.</p><button class="button soft" data-action="add-task">${icon('plus')} Añadir tarea</button></div>`}</section><section class="panel" style="margin-top:20px"><div class="panel-head"><h3>Próximos exámenes</h3></div>${renderDeadlines(3)}</section><section class="panel" style="margin-top:20px;background:#f5f3ff;border-color:#e8e4ff"><h3>💡 Consejo de estudio</h3><p style="color:#766f98;line-height:1.75;margin:0">Estudia un tema, explícalo con tus propias palabras y después responde preguntas sin mirar los apuntes.</p></section></div></div>`}
function renderSubjectCard(s){let n=topicsFor(s.id).length;return `<button class="subject-card" data-action="open-subject" data-id="${s.id}"><div class="subject-card-top"><span class="color-icon" style="background:${esc(s.color)}22;color:${esc(s.color)}">${icon('book-open')}</span><span class="pill ${pct(s.id)===100&&n?'green':'gray'}">${n?`${pct(s.id)}%`:'Nuevo'}</span></div><div class="name">${esc(s.name)}</div><div class="date">${s.examDate?'Examen · '+niceDate(s.examDate):'Sin fecha de examen'}</div><div class="meta"><span>${n} ${n===1?'tema':'temas'}</span><span>${topicsFor(s.id).filter(x=>x.status==='done').length} completados</span></div><div class="progress-bar"><span style="width:${pct(s.id)}%;background:${esc(s.color)}"></span></div></button>`}
function renderActivity(){let arr=[...db.sessions.map(s=>({date:s.date||today(),text:`${s.minutes} min de concentración`,sub:topic(s.topicId)?.name||'Estudio libre',kind:'⏱️'})),...db.history.map(s=>({date:s.date||today(),text:`Simulacro: ${s.correct}/${s.total} correctas`,sub:subject(s.subjectId)?.name||'Varias asignaturas',kind:'🧠'}))].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4);return arr.map(a=>`<div class="list-row"><span class="icon-dot" style="background:#f3f0ff">${a.kind}</span><div class="info"><div class="title">${esc(a.text)}</div><div class="sub">${esc(a.sub)}</div></div><span class="badge-date">${niceDate(a.date)}</span></div>`).join('')}
function renderTaskRow(t){return `<label class="checkrow"><input type="checkbox" data-task-check="${t.id}" ${t.done?'checked':''}><span class="taskname ${t.done?'done':''}">${esc(t.title)}<small style="display:block;color:var(--muted);margin-top:3px">${esc(topic(t.topicId)?.name||'General')} · ${t.due?niceDate(t.due):'Sin fecha'}</small></span><button type="button" class="button tiny ghost" data-action="delete-task" data-id="${t.id}" aria-label="Eliminar tarea">${icon('trash')}</button></label>`}
function renderDeadlines(limit){let a=db.subjects.filter(s=>s.examDate&&days(s.examDate)>=0).sort((x,y)=>x.examDate.localeCompare(y.examDate)).slice(0,limit);return a.length?a.map(s=>`<div class="deadline"><div class="days">${days(s.examDate)}<small>días</small></div><div class="info"><h4>${esc(s.name)}</h4><p>${niceDate(s.examDate)}</p></div><span class="pill orange">Examen</span></div>`).join(''):`<div style="color:var(--muted);font-size:12px;line-height:1.7">Todavía no has añadido fechas de examen. Puedes indicarlas al crear o editar una asignatura.</div>`}
function renderSubjects(){if(!activeSubject||!subject(activeSubject))activeSubject=db.subjects[0]?.id||null;let s=subject(activeSubject),ts=s?topicsFor(s.id):[];return `<div class="section-row"><div><h1>Mis asignaturas</h1><p>Divide el temario en unidades pequeñas y marca tu avance.</p></div><div class="section-actions"><button class="button" data-action="add-subject">${icon('plus')} Nueva asignatura</button></div></div>${!db.subjects.length?empty('🎓','Tu temario, en un solo lugar','Empieza creando una asignatura. Después podrás añadir temas, apuntes, recursos y preguntas.','Crear asignatura','add-subject'):`<div class="split"><section class="panel"><div class="panel-head"><h3>Asignaturas</h3><span class="pill gray">${db.subjects.length} en total</span></div><div class="subject-menu">${db.subjects.map(x=>`<button class="subject-choice ${x.id===activeSubject?'active':''}" data-action="select-subject" data-id="${x.id}"><span class="color-line" style="background:${esc(x.color)}"></span><span style="min-width:0;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(x.name)}</span><span class="count">${topicsFor(x.id).length}</span></button>`).join('')}</div><div class="separator"></div><button class="button soft" data-action="add-subject" style="width:100%">${icon('plus')} Nueva asignatura</button></section><div><section class="panel"><div class="panel-head"><div><h2>${esc(s.name)}</h2><div class="muted small">${s.examDate?'Examen: '+niceDate(s.examDate):'Examen sin fecha'}</div></div><div class="flex"><button class="button ghost tiny" data-action="edit-subject" data-id="${s.id}">${icon('edit')} Editar</button><button class="button danger tiny" data-action="delete-subject" data-id="${s.id}">${icon('trash')}</button></div></div><div class="progress-line"><span class="small muted">Avance</span><div class="progress-bar"><span style="width:${pct(s.id)}%;background:${esc(s.color)}"></span></div><b class="small">${pct(s.id)}%</b></div><div class="separator"></div><div class="panel-head"><h3>Temario</h3><button class="button tiny" data-action="add-topic">${icon('plus')} Añadir tema</button></div>${!ts.length?empty('🗂️','Todavía no hay temas','Añade las unidades del programa de tu examen.','Nuevo tema','add-topic'):ts.map(t=>`<div class="topic-row"><div class="topic-left"><span class="circle-progress">${t.status==='done'?icon('check'):icon('file-text')}</span><div><h3>${esc(t.name)}</h3><div class="desc"><span>${allTopicCards(t.id).length} tarjetas</span><span>${db.materials.filter(m=>m.topicId===t.id).length} recursos</span><span>${t.priority===3?'Prioridad alta':t.priority===1?'Prioridad baja':'Prioridad media'}</span></div></div></div><div class="flex"><select data-topic-status="${t.id}" aria-label="Estado del tema ${esc(t.name)}" class="input" style="width:145px;padding:8px;font-size:11px"><option value="new" ${t.status==='new'?'selected':''}>Sin empezar</option><option value="studying" ${t.status==='studying'?'selected':''}>En estudio</option><option value="done" ${t.status==='done'?'selected':''}>Completado</option></select><button class="button tiny soft" data-action="open-topic" data-id="${t.id}">Abrir ${icon('arrow')}</button><button class="button tiny ghost" data-action="edit-topic" data-id="${t.id}" aria-label="Editar tema">${icon('edit')}</button></div></div>`).join('')}</section><div class="note" style="margin-top:17px">Marca los temas como «Completado» cuando domines el contenido. En «Material» podrás añadir apuntes y convertir definiciones en tarjetas de estudio.</div></div></div>`}`}
function renderMaterial(){if(!activeTopic||!topic(activeTopic))activeTopic=db.topics[0]?.id||null;let t=topic(activeTopic),s=t?subject(t.subjectId):null;return `<div class="section-row"><div><h1>Material de estudio</h1><p>Apuntes, textos y documentos organizados por temática.</p></div><div class="section-actions"><button class="button ghost" data-action="add-topic">${icon('plus')} Tema</button><button class="button" data-action="add-material" ${!t?'disabled':''}>${icon('upload')} Añadir material</button></div></div>${!db.topics.length?empty('📂','Primero crea un tema','Cada recurso se guarda dentro de un tema. Crea una asignatura y añade su temario para empezar.','Ir a asignaturas','go-subjects'):`<div class="material-layout"><section class="panel"><h3>Explorar temario</h3><div class="topic-list">${db.subjects.map(s=>`<div style="font-size:10px;color:var(--muted);font-weight:850;letter-spacing:.8px;text-transform:uppercase;margin:13px 10px 4px">${esc(s.name)}</div>${topicsFor(s.id).map(x=>`<button class="topic-pick ${x.id===activeTopic?'active':''}" data-action="select-topic" data-id="${x.id}"><span class="topicname">${esc(x.name)}</span><small>${allTopicCards(x.id).length} tarjetas · ${db.materials.filter(m=>m.topicId===x.id).length} recursos</small></button>`).join('')}`).join('')}</div></section><div><section class="panel"><div class="panel-head"><div><div class="small muted" style="margin-bottom:7px">${esc(s?.name||'')}</div><h2 style="margin:0">${esc(t?.name||'')}</h2></div><span class="pill">${esc(t?.status==='done'?'Completado':t?.status==='studying'?'En estudio':'Sin empezar')}</span></div><div class="panel-head" style="margin-top:28px;margin-bottom:12px"><h3>Mis apuntes</h3><span class="small muted" id="note-status">Guardado automáticamente</span></div><textarea id="topic-notes" data-note="${t.id}" class="editor" spellcheck="true" placeholder="Escribe tus resúmenes, conceptos, preguntas clave, definiciones...">${esc(t.notes||'')}</textarea><div class="note" style="margin-top:12px">Truco: escribe <b>Concepto: definición</b> en líneas separadas. Faro podrá transformarlas en tarjetas y utilizarlas para crear simulacros de este tema.</div><div class="separator"></div><div class="panel-head"><h3>Recursos y documentos</h3><button class="button tiny ghost" data-action="add-material">${icon('plus')} Añadir</button></div><div class="materials-list">${db.materials.filter(m=>m.topicId===t.id).length?db.materials.filter(m=>m.topicId===t.id).map(m=>`<div class="material-item"><div class="doc-icon">${icon('file-text')}</div><div class="doc-info"><h4>${esc(m.title)}</h4><p>${esc(m.kind||'Texto')} · ${Math.round((m.text||'').length/1000*10)/10} mil caracteres · ${niceDate(m.date||today())}</p></div><button class="button tiny ghost" data-action="read-material" data-id="${m.id}">Abrir</button><button class="button tiny danger" data-action="delete-material" data-id="${m.id}" aria-label="Eliminar documento">${icon('trash')}</button></div>`).join(''):empty('📄','Sin documentos todavía','Pega texto o carga archivos PDF, Word, TXT y Markdown para organizar tus contenidos.','Añadir material','add-material')}</div><div class="separator"></div><div class="panel-head"><div><h3>Tarjetas de este tema</h3><span class="small muted">${allTopicCards(t.id).length} creadas</span></div><div class="flex"><button class="button tiny ghost" data-action="generate-cards">${icon('star')} Generar desde apuntes</button><button class="button tiny soft" data-action="add-card">${icon('plus')} Nueva tarjeta</button></div></div>${allTopicCards(t.id).length?allTopicCards(t.id).slice(0,8).map(c=>`<div class="list-row"><span class="icon-dot" style="background:#f3f1ff;color:var(--violet)">${icon('layers')}</span><div class="info"><div class="title">${esc(c.front)}</div><div class="sub">${esc(c.back.slice(0,110))}${c.back.length>110?'…':''}</div></div><button class="button tiny ghost" data-action="edit-card" data-id="${c.id}">${icon('edit')}</button><button class="button tiny danger" data-action="delete-card" data-id="${c.id}">${icon('trash')}</button></div>`).join(''):`<div class="muted small">Añade preguntas con su respuesta, o genera tarjetas a partir de definiciones en tus materiales.</div>`}</section></div></div>`}`}
function renderPlan(){let un=db.tasks.filter(t=>!t.done).sort((a,b)=>(a.due||'9').localeCompare(b.due||'9')),done=db.tasks.filter(t=>t.done).length;return `<div class="section-row"><div><h1>Planificador</h1><p>Transforma tus objetivos en pequeñas sesiones de estudio.</p></div><button class="button" data-action="add-task">${icon('plus')} Nueva tarea</button></div><div class="stats" style="grid-template-columns:repeat(3,minmax(0,1fr))">${stat(un.length,'Tareas pendientes','calendar')}${stat(done,'Tareas realizadas','check','green')}${stat(nearest()?Math.max(0,days(nearest().examDate)):'—','Días hasta el próximo examen','clock','orange')}</div><div class="grid2"><div><section class="panel"><div class="panel-head"><h3>Lista de estudio</h3><button class="button tiny soft" data-action="add-task">${icon('plus')} Añadir</button></div>${un.length?un.map(renderTaskRow).join(''):empty('📝','¡Todo al día!','No tienes tareas pendientes. Organiza el siguiente bloque de estudio.','Añadir tarea','add-task')}${db.tasks.some(t=>t.done)?`<div class="separator"></div><details><summary style="font-weight:750;cursor:pointer;color:var(--muted)">Tareas completadas (${done})</summary><div style="margin-top:16px">${db.tasks.filter(t=>t.done).map(renderTaskRow).join('')}</div></details>`:''}</section><section class="panel" style="margin-top:20px"><div class="panel-head"><h3>Fechas importantes</h3><button class="link-btn" data-nav="subjects">Editar fechas</button></div>${renderDeadlines(20)}</section></div><div><section class="panel"><h3>Sesión de concentración</h3><p class="small muted">Estudia sin distracciones. El tiempo completado se añadirá a tu progreso.</p><div class="focus-box"><div class="small semibold" style="margin-bottom:12px;color:#7a71bb">TEMPORIZADOR POMODORO</div><div id="focus-display" class="focus-time">25:00</div><p id="focus-label">Listo para empezar</p><div class="flex" style="justify-content:center;margin-top:14px"><button class="button tiny ghost" data-action="focus-preset" data-value="15">15 min</button><button class="button tiny ghost" data-action="focus-preset" data-value="25">25 min</button><button class="button tiny ghost" data-action="focus-preset" data-value="45">45 min</button></div></div><div class="field" style="margin-top:17px"><label>¿Qué tema vas a estudiar?</label><select id="focus-topic" class="input"><option value="">Estudio general</option>${db.topics.map(t=>`<option value="${t.id}" ${t.id===focus.topicId?'selected':''}>${esc(subject(t.subjectId)?.name||'')} / ${esc(t.name)}</option>`).join('')}</select></div><div class="flex"><button class="button" data-action="focus-start" id="focus-btn">${icon('play')} Empezar</button><button class="button ghost" data-action="focus-reset">Reiniciar</button></div></section><div class="note" style="margin-top:16px">Planifica repasos cortos de los temas difíciles, dejando tiempo para un simulacro antes de cada examen.</div></div></div>`}
function getFilteredCards(filter){if(filter==='all')return db.cards;return db.cards.filter(c=>topic(c.topicId)?.subjectId===filter||c.topicId===filter)}
function renderPractice(){let cards=getFilteredCards(practiceMode==='repaso'?reviewFilter:quizFilter),due=cards.filter(c=>!c.due||c.due<=today());return `<div class="section-row"><div><h1>Practica y recuerda</h1><p>Repaso activo con tarjetas y simulacros por asignatura o tema.</p></div><button class="button ghost" data-action="add-card">${icon('plus')} Crear tarjeta</button></div><div class="tabs"><button data-action="mode" data-value="repaso" class="${practiceMode==='repaso'?'active':''}">Tarjetas de repaso</button><button data-action="mode" data-value="examen" class="${practiceMode==='examen'?'active':''}">Simulacro de examen</button></div>${practiceMode==='repaso'?renderReview(cards,due):renderExam(cards)}`}
function filterOptions(selected){return `<option value="all">Todas las asignaturas</option>${db.subjects.map(s=>`<optgroup label="${esc(s.name)}"><option value="${s.id}" ${selected===s.id?'selected':''}>Toda ${esc(s.name)}</option>${topicsFor(s.id).map(t=>`<option value="${t.id}" ${selected===t.id?'selected':''}>↳ ${esc(t.name)}</option>`).join('')}</optgroup>`).join('')}`}
function renderReview(cards,due){const c=due[0]||cards[0];return `<div class="filterbar"><select id="review-filter" aria-label="Filtrar tarjetas">${filterOptions(reviewFilter)}</select><span class="pill gray">${cards.length} tarjetas</span><span class="pill orange">${due.length} pendientes</span><span class="spacer"></span><button class="button tiny ghost" data-action="add-card">${icon('plus')} Nueva tarjeta</button></div>${!cards.length?empty('🧠','Sin tarjetas todavía','Crea preguntas con respuestas en tus temas. También puedes generarlas a partir de apuntes con formato de definición.','Ir al material','go-material'):!due.length?`<div class="panel">${empty('🎉','¡Repaso del día completado!','Has revisado todas las tarjetas pendientes de este filtro. Puedes volver mañana o practicar con un simulacro.')}</div>`:`<div class="quiz-wrap"><div class="quiz-top"><span>${esc(topic(c.topicId)?.name||'Tema')}</span><span>Próximas a repasar: ${due.length}</span></div><div class="flashcard" role="button" tabindex="0" data-action="flip-card"><span class="subtle">${reviewFlipped?'RESPUESTA':'PREGUNTA'}</span><div class="big">${esc(reviewFlipped?c.back:c.front)}</div><span class="tip">${reviewFlipped?'¿Qué tal la has recordado?':'Haz clic para ver la respuesta'}</span></div><div class="review-actions">${!reviewFlipped?`<button class="button" data-action="flip-card">Mostrar respuesta ${icon('arrow')}</button>`:`<button class="button danger" data-action="grade-card" data-id="${c.id}" data-value="again">Otra vez</button><button class="button soft" data-action="grade-card" data-id="${c.id}" data-value="good">Bien (+3 días)</button><button class="button" data-action="grade-card" data-id="${c.id}" data-value="easy">Fácil (+7 días)</button>`}</div><div class="note">Recuerda la respuesta antes de voltear la tarjeta. Los intervalos de repaso se ajustan a tu autoevaluación.</div></div>`}`}
function renderExam(cards){return `<div class="filterbar"><select id="quiz-filter" aria-label="Elegir temática del simulacro">${filterOptions(quizFilter)}</select><span class="pill gray">${cards.length} preguntas disponibles</span></div>${quiz?renderQuiz():`<div class="grid2 equal"><div class="panel"><div style="font-size:45px;margin-bottom:14px">📝</div><h2>Simulacro por temáticas</h2><p style="color:var(--muted);line-height:1.7">Elige una asignatura o tema y practica con hasta 10 preguntas. Cuando haya suficientes respuestas diferentes, aparecerán opciones múltiples; en los demás casos, podrás evaluar tu respuesta.</p><div class="note" style="margin:18px 0 20px">Las preguntas salen de tus tarjetas. No se envía tu material a ningún servicio externo ni se utiliza inteligencia artificial en esta versión.</div><button class="button" data-action="start-quiz" ${!cards.length?'disabled':''}>${icon('play')} Empezar simulacro</button></div><div class="panel"><h3>Cómo prepararte</h3><div class="list-row"><span class="icon-dot" style="background:#f0edff">1</span><div class="info"><div class="title">Organiza tus temas</div><div class="sub">Divide el examen en unidades y conceptos.</div></div></div><div class="list-row"><span class="icon-dot" style="background:#f0edff">2</span><div class="info"><div class="title">Crea tarjetas de conocimiento</div><div class="sub">Añade preguntas y respuestas desde Material.</div></div></div><div class="list-row"><span class="icon-dot" style="background:#f0edff">3</span><div class="info"><div class="title">Haz simulacros y repite</div><div class="sub">Revisa tus resultados en Mi progreso.</div></div></div></div></div>`}`}
function norm(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim()}
function shuffle(arr){let a=[...arr];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function makeQuiz(cards){let chosen=shuffle(cards).slice(0,Math.min(10,cards.length));return chosen.map(c=>{let answers=[...new Set(cards.map(x=>x.back.trim()))].filter(a=>norm(a)!==norm(c.back)&&a.length<170);let opts=answers.length>=2&&c.back.length<170?shuffle([c.back,...shuffle(answers).slice(0,3)]):[];return {id:c.id,front:c.front,back:c.back,options:opts,selected:null,grade:null}})}
function renderQuiz(){let q=quiz;if(q.idx>=q.items.length){let correct=q.items.filter(i=>i.grade===true).length,total=q.items.length;return `<div class="panel quiz-wrap" style="text-align:center;padding:45px"><div style="font-size:54px">${correct/total>=.7?'🏆':'💪'}</div><h2>¡Simulacro terminado!</h2><div style="font-size:50px;font-weight:850;color:var(--violet);margin:14px 0">${Math.round(correct/total*100)}%</div><p class="muted">Has acertado ${correct} de ${total} preguntas.</p><div class="review-actions"><button class="button" data-action="exit-quiz">Volver a practicar</button><button class="button ghost" data-action="repeat-quiz">Repetir</button></div></div>`}let item=q.items[q.idx],answered=item.grade!==null;return `<div class="quiz-wrap"><div class="quiz-top"><span>Pregunta ${q.idx+1} de ${q.items.length}</span><span>Simulacro de examen</span></div><div class="progress-bar"><span style="width:${(q.idx/q.items.length)*100}%"></span></div><div class="panel" style="margin-top:19px"><div class="small muted">PREGUNTA ${q.idx+1}</div><div class="quiz-question">${esc(item.front)}</div>${item.options.length?item.options.map((o,i)=>`<button class="quiz-option ${answered?(norm(o)===norm(item.back)?'correct':norm(o)===norm(item.selected)?'wrong':''):''}" data-action="quiz-option" data-value="${i}" ${answered?'disabled':''}><span class="opt-letter">${'ABCD'[i]}</span><span>${esc(o)}</span></button>`).join(''):`<div class="field"><label>Tu respuesta (mental o por escrito)</label><textarea class="editor" id="quiz-written" style="min-height:125px" ${answered?'disabled':''} placeholder="Intenta responder antes de ver la solución">${esc(item.selected||'')}</textarea></div>${!answered?`<button class="button soft" data-action="quiz-reveal">Mostrar solución</button>`:''}`}${answered?`<div class="feedback"><strong>${item.options.length?(item.grade?'✅ Respuesta correcta':'📌 Respuesta a revisar'):'Respuesta de referencia'}</strong>${esc(item.back)}</div>${!item.options.length?`<div class="flex"><button class="button ghost" data-action="quiz-grade" data-value="wrong">No la recordé</button><button class="button" data-action="quiz-grade" data-value="right">La recordé bien</button></div>`:`<button class="button" data-action="next-question">${q.idx===q.items.length-1?'Ver resultados':'Siguiente pregunta'} ${icon('arrow')}</button>`}`:''}</div><div class="small muted" style="margin-top:15px">${item.options.length?'Selecciona la opción que consideres correcta.':'Compara tu respuesta con la solución y evalúate.'}</div></div>`}
function renderProgress(){let total=db.sessions.reduce((a,s)=>a+s.minutes,0),done=db.topics.filter(t=>t.status==='done').length,tests=db.history,rate=tests.length?Math.round(100*tests.reduce((a,x)=>a+x.correct,0)/Math.max(1,tests.reduce((a,x)=>a+x.total,0))):0,counts={};for(let s of db.sessions){counts[s.date]=(counts[s.date]||0)+s.minutes}let heat=Array.from({length:70},(_,i)=>{let d=shiftDay(today(),i-69),n=counts[d]||0;return `<span class="heat ${n>=60?'l4':n>=40?'l3':n>=20?'l2':n>0?'l1':''}" title="${niceDate(d)}: ${n} minutos"></span>`}).join('');return `<div class="section-row"><div><h1>Tu progreso</h1><p>Descubre cuánto has avanzado y dónde concentrar tus esfuerzos.</p></div><button class="button ghost" data-action="export">${icon('download')} Exportar datos</button></div><div class="stats">${stat(total,'Minutos de estudio','clock')}${stat(done,'Temas dominados','check','green')}${stat(tests.length,'Simulacros realizados','brain','orange')}${stat(tests.length?rate+'%':'—','Aciertos en simulacros','chart','pink')}</div><div class="grid2"><div><section class="panel"><div class="panel-head"><h3>Avance por asignatura</h3></div>${db.subjects.length?`<div class="bar-chart">${db.subjects.map(s=>`<div class="bar-item"><div class="bar-head"><strong>${esc(s.name)}</strong><span class="muted">${pct(s.id)}%</span></div><div class="progress-bar"><span style="width:${pct(s.id)}%;background:${esc(s.color)}"></span></div></div>`).join('')}</div>`:empty('📊','Aún no hay datos','Crea tus asignaturas y marca temas como completados para medir tu avance.')}</section><section class="panel" style="margin-top:20px"><div class="panel-head"><h3>Últimos simulacros</h3></div>${tests.length?tests.slice(-8).reverse().map(h=>`<div class="list-row"><span class="icon-dot" style="background:#f2f0ff">🧠</span><div class="info"><div class="title">${esc(subject(h.subjectId)?.name||'Varios temas')}</div><div class="sub">${niceDate(h.date)} · ${h.total} preguntas</div></div><span class="pill ${h.correct/h.total>=.7?'green':'orange'}">${Math.round(100*h.correct/h.total)}%</span></div>`).join(''):`<p class="muted small">Cuando hagas un simulacro, tus resultados aparecerán aquí.</p>`}</section></div><div><section class="panel"><h3>Constancia de los últimos 70 días</h3><p class="small muted">Cada cuadro representa un día con sesiones registradas.</p><div class="heatmap" style="margin:23px 0 9px">${heat}</div><div class="flex" style="font-size:11px;color:var(--muted);justify-content:flex-end"><span>Menos</span><span class="heat" style="width:11px;background:#f0f0f5"></span><span class="heat l1" style="width:11px"></span><span class="heat l2" style="width:11px"></span><span class="heat l3" style="width:11px"></span><span class="heat l4" style="width:11px"></span><span>Más</span></div></section><section class="panel" style="margin-top:20px"><h3>Lo próximo</h3><p class="small muted" style="line-height:1.7">Repasa ${dueCards().length} tarjetas pendientes y completa tus ${db.tasks.filter(t=>!t.done).length} tareas programadas. El rendimiento mejora con sesiones frecuentes y recuperación activa.</p><button class="button" data-nav="practice">Practicar ahora ${icon('arrow')}</button></section></div></div>`}
function showModal(title,html,wide=false){document.getElementById('modal-root').innerHTML=`<div class="modal-back" data-overlay="true"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="xbtn" data-action="close-modal" aria-label="Cerrar">×</button></div><div class="modal-body">${html}</div></div></div>`;const e=document.querySelector('.modal input:not([type=hidden]),.modal textarea,.modal select');e?.focus()}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
const palette=['#7463eb','#eb8f58','#219c88','#e56b93','#4585d2','#a07c4d'];
function subjectModal(x){showModal(x?'Editar asignatura':'Nueva asignatura',`<form data-form="subject"><input type="hidden" name="sid" value="${esc(x?.id||'')}"><div class="field"><label>Nombre de la asignatura *</label><input name="name" required maxlength="90" placeholder="Ej. Anatomía, Historia, Matemáticas..." value="${esc(x?.name||'')}"></div><div class="field"><label>Fecha del examen (opcional)</label><input type="date" name="examDate" value="${esc(x?.examDate||'')}"></div><div class="field"><label>Color para identificarla</label><div class="flex">${palette.map((c,i)=>`<label style="display:flex;gap:4px;align-items:center;font-size:11px"><input type="radio" name="color" value="${c}" ${(x?.color||palette[0])===c?'checked':''} style="accent-color:${c}"><span style="width:23px;height:23px;background:${c};border-radius:7px"></span></label>`).join('')}</div></div><div class="modal-foot"><button type="button" class="button ghost" data-action="close-modal">Cancelar</button><button type="submit" class="button">Guardar</button></div></form>`)}
function topicModal(x){if(!db.subjects.length){subjectModal();return}let selected=x?.subjectId||activeSubject||db.subjects[0].id;showModal(x?'Editar tema':'Nuevo tema',`<form data-form="topic"><input type="hidden" name="tid" value="${esc(x?.id||'')}"><div class="field"><label>Asignatura *</label><select name="subjectId" required>${db.subjects.map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Nombre del tema *</label><input name="name" required maxlength="120" value="${esc(x?.name||'')}" placeholder="Ej. Funciones y ecuaciones"></div><div class="twocol"><div class="field"><label>Prioridad</label><select name="priority"><option value="1" ${x?.priority===1?'selected':''}>Baja</option><option value="2" ${!x||x.priority===2?'selected':''}>Media</option><option value="3" ${x?.priority===3?'selected':''}>Alta</option></select></div><div class="field"><label>Estado</label><select name="status"><option value="new" ${!x||x.status==='new'?'selected':''}>Sin empezar</option><option value="studying" ${x?.status==='studying'?'selected':''}>En estudio</option><option value="done" ${x?.status==='done'?'selected':''}>Completado</option></select></div></div><div class="modal-foot"><button type="button" class="button ghost" data-action="close-modal">Cancelar</button><button type="submit" class="button">Guardar tema</button></div></form>`)}
function cardModal(c){if(!db.topics.length){toast('Añade primero una asignatura y un tema.');goto('subjects');return}let selected=c?.topicId||activeTopic||db.topics[0].id;showModal(c?'Editar tarjeta':'Nueva tarjeta de estudio',`<form data-form="card"><input type="hidden" name="cid" value="${esc(c?.id||'')}"><div class="field"><label>Tema</label><select name="topicId">${db.topics.map(t=>`<option value="${t.id}" ${t.id===selected?'selected':''}>${esc(subject(t.subjectId)?.name||'')} / ${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>Pregunta o concepto *</label><textarea name="front" required maxlength="600" rows="3" placeholder="¿Qué es la fotosíntesis?">${esc(c?.front||'')}</textarea></div><div class="field"><label>Respuesta *</label><textarea name="back" required maxlength="3500" rows="4" placeholder="Es el proceso mediante el cual...">${esc(c?.back||'')}</textarea></div><div class="modal-foot"><button type="button" class="button ghost" data-action="close-modal">Cancelar</button><button type="submit" class="button">Guardar tarjeta</button></div></form>`)}
function taskModal(){showModal('Nueva tarea de estudio',`<form data-form="task"><div class="field"><label>¿Qué necesitas estudiar? *</label><input name="title" required maxlength="180" placeholder="Ej. Resolver ejercicios del tema 3"></div><div class="field"><label>Temática (opcional)</label><select name="topicId"><option value="">General</option>${db.topics.map(t=>`<option value="${t.id}">${esc(subject(t.subjectId)?.name||'')} / ${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>Fecha prevista</label><input type="date" name="due" value="${today()}"></div><div class="modal-foot"><button type="button" class="button ghost" data-action="close-modal">Cancelar</button><button class="button" type="submit">Añadir tarea</button></div></form>`)}
function materialModal(){if(!db.topics.length){toast('Crea primero un tema.');goto('subjects');return}let tid=activeTopic||db.topics[0].id;showModal('Añadir material de estudio',`<div class="note" style="margin-bottom:16px">Puedes pegar texto o importar PDF, Word (.docx), TXT, Markdown o HTML. Los archivos PDF y Word requieren conexión a internet para extraer su texto.</div><form data-form="material"><div class="field"><label>Tema</label><select name="topicId">${db.topics.map(t=>`<option value="${t.id}" ${t.id===tid?'selected':''}>${esc(subject(t.subjectId)?.name||'')} / ${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>Título *</label><input name="title" maxlength="140" required placeholder="Ej. Resumen del capítulo 2"></div><div class="field"><label>Pegar texto (opcional si vas a importar archivo)</label><textarea name="text" rows="7" placeholder="Pega tus apuntes, definiciones, conceptos..." style="min-height:125px"></textarea></div><div class="field"><label>O seleccionar un documento</label><div class="file-drop"><input type="file" name="file" accept=".txt,.md,.markdown,.csv,.html,.htm,.pdf,.docx,.json"><p class="field-hint" style="margin:10px 0 0">TXT, MD, CSV, HTML, PDF y DOCX · máx. 15 MB</p></div></div><div class="modal-foot"><button type="button" class="button ghost" data-action="close-modal">Cancelar</button><button type="submit" class="button" id="material-save">Importar / guardar</button></div></form>`)}
function readMaterial(m){showModal(m.title,`<p class="muted small">${esc(topic(m.topicId)?.name||'')} · ${niceDate(m.date||today())}</p><div class="material-read">${esc(m.text)}</div><div class="modal-foot"><button class="button ghost" data-action="close-modal">Cerrar</button><button class="button soft" data-action="generate-material" data-id="${m.id}">${icon('star')} Crear tarjetas de este texto</button></div>`,true)}
function settingsModal(){showModal('Ajustes y copias de seguridad',`<p style="line-height:1.7;color:var(--muted)">Tus materiales se guardan <b>en este navegador y dispositivo</b>. No hay cuentas ni sincronización con la nube. Crea una copia para evitar perder información si borras los datos del navegador.</p><div class="panel" style="box-shadow:none;margin-bottom:14px"><h3>Exportar datos</h3><p class="small muted">Descarga todas tus materias, tarjetas, recursos y progreso como archivo JSON.</p><button class="button soft" data-action="export">${icon('download')} Descargar copia .json</button></div><div class="panel" style="box-shadow:none;margin-bottom:14px"><h3>Restaurar copia</h3><p class="small muted">Importa una copia guardada anteriormente. Reemplaza los datos actuales.</p><input id="backup-input" class="input" type="file" accept=".json,application/json"></div><div class="panel" style="box-shadow:none"><h3>Zona de datos</h3><p class="small muted">Si solo quieres probar Faro, puedes cargar contenido de demostración.</p><div class="flex"><button class="button ghost tiny" data-action="demo">Cargar ejemplo</button><button class="button danger tiny" data-action="reset-db">Borrar todo</button></div></div>`)}
function download(name,txt,type){let b=new Blob([txt],{type:type||'text/plain;charset=utf-8'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function generateFrom(text,tid,max=24){let pairs=[],lines=String(text||'').replace(/\r/g,'').split(/\n+/);for(let line of lines){line=line.replace(/^\s*(?:[•*-]|\d+[.)])\s*/,'').trim();if(line.length<14||line.length>650)continue;let match=line.match(/^([^:]{3,80}):\s*(.{8,550})$/);if(!match)match=line.match(/^(.{3,80}?)\s+[–—-]\s+(.{10,550})$/);if(match){let front=match[1].replace(/^#+\s*/,'').trim(),back=match[2].trim();if(front.length>3&&back.length>8)pairs.push([front.endsWith('?')?front:`¿Qué es ${front.replace(/[.!?]$/,'')}?`,back]);continue}let m=line.match(/^(?:El|La|Los|Las|Un|Una)\s+([\p{L}][\p{L}0-9 ,]{3,65}?)\s+(?:es|son|consiste en|se define como|se refiere a)\s+(.{12,500})[.]?$/iu);if(m){let term=m[1].trim(),def=m[2].trim();pairs.push([`¿Qué es ${term}?`,def])}}let existing=new Set(db.cards.filter(c=>c.topicId===tid).map(c=>norm(c.front))),created=0;for(let [front,back] of pairs){if(created>=max)break;if(existing.has(norm(front)))continue;db.cards.push({id:id(),topicId:tid,front,back,box:0,due:today(),reps:0,createdAt:today()});existing.add(norm(front));created++}return created}
function textOfTopic(tid){let t=topic(tid);return [t?.notes||'',...db.materials.filter(m=>m.topicId===tid).map(m=>m.text||'')].join('\n')}
function library(url){return new Promise((ok,fail)=>{let existing=document.querySelector(`script[data-lib="${url}"]`);if(existing){if(existing.dataset.loaded==='1')return ok();existing.addEventListener('load',ok,{once:true});existing.addEventListener('error',()=>fail(new Error('No se pudo cargar el procesador de archivos. Comprueba tu conexión.')),{once:true});return}let s=document.createElement('script');s.src=url;s.dataset.lib=url;s.onload=()=>{s.dataset.loaded='1';ok()};s.onerror=()=>fail(new Error('No se pudo cargar el procesador de archivos. Comprueba tu conexión.'));document.head.appendChild(s)})}
async function extractFile(file){if(file.size>15*1024*1024)throw new Error('El archivo supera los 15 MB.');let name=file.name.toLowerCase();if(/\.(txt|md|markdown|csv|html|htm|json)$/.test(name)){let tx=await file.text();if(/\.html?$/.test(name)){let doc=new DOMParser().parseFromString(tx,'text/html');tx=doc.body?.innerText||doc.body?.textContent||tx}return tx}if(name.endsWith('.pdf')){await library('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');let pdfjs=window.pdfjsLib;if(!pdfjs)throw new Error('No se pudo iniciar el lector PDF.');pdfjs.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';let d=await pdfjs.getDocument({data:await file.arrayBuffer()}).promise,all=[];for(let p=1;p<=Math.min(d.numPages,100);p++){let page=await d.getPage(p),content=await page.getTextContent();all.push(content.items.map(i=>i.str).join(' '));if(all.join('').length>180000)break}return all.join('\n')}if(name.endsWith('.docx')){await library('https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.8.0/mammoth.browser.min.js');if(!window.mammoth)throw new Error('No se pudo iniciar el lector de Word.');let out=await window.mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});return out.value}throw new Error('Tipo de archivo no admitido.')}
function demo(){if(db.subjects.length&&!confirm('El ejemplo se añadirá a tus asignaturas existentes. ¿Continuar?'))return;let sid=id(),t1=id(),t2=id();db.subjects.push({id:sid,name:'Biología · ejemplo',color:'#219c88',examDate:shiftDay(today(),21),createdAt:today()});db.topics.push({id:t1,subjectId:sid,name:'La célula',priority:2,status:'studying',notes:'Membrana plasmática: estructura que regula el intercambio de sustancias entre la célula y el medio.\nNúcleo: orgánulo que contiene la mayor parte del material genético.\nCitoplasma: región celular situada entre la membrana plasmática y el núcleo.'},{id:t2,subjectId:sid,name:'Fotosíntesis',priority:3,status:'new',notes:'Fotosíntesis: proceso por el que las plantas convierten energía luminosa en energía química.\nCloroplasto: orgánulo celular donde ocurre la fotosíntesis.\nClorofila: pigmento que capta la energía de la luz.'});generateFrom(db.topics.find(t=>t.id===t1).notes,t1);generateFrom(db.topics.find(t=>t.id===t2).notes,t2);db.tasks.push({id:id(),title:'Repasar la célula y sus orgánulos',topicId:t1,due:today(),done:false});activeSubject=sid;activeTopic=t1;save();closeModal();goto('home');toast('Ejemplo cargado. Puedes editarlo o eliminarlo cuando quieras.')}
function updateFocusUI(){let display=document.getElementById('focus-display'),btn=document.getElementById('focus-btn'),label=document.getElementById('focus-label');if(!display)return;display.textContent=String(Math.floor(focus.seconds/60)).padStart(2,'0')+':'+String(focus.seconds%60).padStart(2,'0');if(label)label.textContent=focus.running?'Sesión en curso · ¡tú puedes!':'Listo para empezar';if(btn)btn.innerHTML=focus.running?`${icon('pause')} Pausar`:`${icon('play')} ${focus.seconds===focus.initial?'Empezar':'Continuar'}`}
function stopFocus(saveSession){if(focus.timer){clearInterval(focus.timer);focus.timer=null}focus.running=false;if(saveSession){let mins=Math.max(1,Math.round((focus.initial-focus.seconds)/60));db.sessions.push({id:id(),topicId:focus.topicId,minutes:mins,date:today()});save();toast(`Sesión guardada: ${mins} min. ¡Bien hecho!`)}updateFocusUI()}
function handleAction(el){let action=el.dataset.action,vid=el.dataset.id,val=el.dataset.value;switch(action){case'close-modal':closeModal();break;case'settings':settingsModal();break;case'add-subject':subjectModal();break;case'edit-subject':subjectModal(subject(vid));break;case'delete-subject':{let s=subject(vid);if(!s||!confirm(`¿Eliminar «${s.name}» y todos sus temas, materiales y tarjetas?`))break;let ids=topicsFor(vid).map(t=>t.id);db.subjects=db.subjects.filter(x=>x.id!==vid);db.topics=db.topics.filter(t=>t.subjectId!==vid);db.cards=db.cards.filter(c=>!ids.includes(c.topicId));db.materials=db.materials.filter(m=>!ids.includes(m.topicId));db.tasks=db.tasks.filter(t=>!ids.includes(t.topicId));activeSubject=null;activeTopic=null;save();render();toast('Asignatura eliminada.');break}case'open-subject':case'select-subject':activeSubject=vid;view='subjects';render();break;case'add-topic':topicModal();break;case'edit-topic':topicModal(topic(vid));break;case'open-topic':case'select-topic':activeTopic=vid;activeSubject=topic(vid)?.subjectId;goto('material');break;case'go-subjects':goto('subjects');break;case'go-material':goto('material');break;case'add-material':materialModal();break;case'read-material':readMaterial(db.materials.find(m=>m.id===vid));break;case'delete-material':{let m=db.materials.find(x=>x.id===vid);if(m&&confirm(`¿Eliminar «${m.title}»?`)){db.materials=db.materials.filter(x=>x.id!==vid);save();render();toast('Documento eliminado.')}break}case'generate-cards':{if(!activeTopic)break;let n=generateFrom(textOfTopic(activeTopic),activeTopic);save();render();toast(n?`${n} tarjetas creadas a partir de definiciones.`:'No se detectaron definiciones nuevas. Usa «Concepto: explicación» para generarlas.');break}case'generate-material':{let m=db.materials.find(x=>x.id===vid);if(!m)break;let n=generateFrom(m.text,m.topicId);save();closeModal();activeTopic=m.topicId;goto('material');toast(n?`${n} tarjetas creadas.`:'No se detectaron definiciones nuevas en el texto.');break}case'add-card':cardModal();break;case'edit-card':cardModal(db.cards.find(c=>c.id===vid));break;case'delete-card':if(confirm('¿Eliminar esta tarjeta?')){db.cards=db.cards.filter(c=>c.id!==vid);save();render()}break;case'add-task':taskModal();break;case'delete-task':if(confirm('¿Eliminar esta tarea?')){db.tasks=db.tasks.filter(t=>t.id!==vid);save();render()}break;case'mode':practiceMode=val;quiz=null;reviewFlipped=false;render();break;case'flip-card':reviewFlipped=!reviewFlipped;render();break;case'grade-card':{let c=db.cards.find(x=>x.id===vid);if(!c)break;c.reps=(c.reps||0)+1;c.box=val==='again'?0:(c.box||0)+1;c.due=shiftDay(today(),val==='again'?0:val==='easy'?7:3);if(val==='again'){// Reinsert after other pending cards, but preserve due today.
 db.cards=db.cards.filter(x=>x.id!==vid).concat(c)
 }save();reviewFlipped=false;render();break}case'start-quiz':{let chosen=getFilteredCards(quizFilter);if(!chosen.length){toast('No hay tarjetas en este filtro.');break}quiz={items:makeQuiz(chosen),idx:0,filter:quizFilter,recorded:false};render();break}case'quiz-option':{let i=quiz?.items[quiz.idx];if(!i||i.grade!==null)break;i.selected=i.options[Number(val)];i.grade=norm(i.selected)===norm(i.back);render();break}case'quiz-reveal':{let i=quiz?.items[quiz.idx];if(!i)break;i.selected=document.getElementById('quiz-written')?.value||'';i.grade='pending';render();break}case'quiz-grade':{let i=quiz?.items[quiz.idx];if(!i)break;i.grade=val==='right';finishOrNext();break}case'next-question':finishOrNext();break;case'exit-quiz':quiz=null;render();break;case'repeat-quiz':quiz=null;handleAction({dataset:{action:'start-quiz'}});break;case'focus-preset':{if(focus.running)stopFocus(false);focus.initial=focus.seconds=Number(val)*60;updateFocusUI();break}case'focus-start':{if(focus.running){stopFocus(false);break}focus.topicId=document.getElementById('focus-topic')?.value||'';focus.running=true;focus.timer=setInterval(()=>{if(!focus.running)return;focus.seconds--;updateFocusUI();if(focus.seconds<=0){stopFocus(true);focus.seconds=focus.initial;updateFocusUI();toast('¡Has completado tu sesión de concentración!')}},1000);updateFocusUI();break}case'focus-reset':{if(focus.running||focus.seconds<focus.initial){let elapsed=focus.initial-focus.seconds;if(elapsed>=60&&confirm('¿Guardar los minutos estudiados antes de reiniciar?'))stopFocus(true);else stopFocus(false)}focus.seconds=focus.initial;updateFocusUI();break}case'export':download('faro-copia-'+today()+'.json',JSON.stringify(db,null,2),'application/json');toast('Copia descargada.');break;case'reset-db':if(confirm('¿Seguro que deseas borrar TODOS los datos locales de Faro? Esta acción no se puede deshacer.')){db=blank();activeSubject=activeTopic=null;save();closeModal();goto('home');toast('Datos borrados.')}break;case'demo':demo();break}}
function finishOrNext(){if(!quiz)return;quiz.idx++;if(quiz.idx>=quiz.items.length&&!quiz.recorded){let correct=quiz.items.filter(i=>i.grade===true).length,total=quiz.items.length;let selected=quiz.filter,sub=subject(selected)?selected:topic(selected)?.subjectId||null;db.history.push({id:id(),date:today(),correct,total,subjectId:sub,topicId:topic(selected)?.id||null});quiz.recorded=true;save()}render()}
async function handleForm(form){const data=new FormData(form),type=form.dataset.form,formVal=k=>String(data.get(k)||'').trim();if(type==='subject'){let x=subject(formVal('sid'));let obj={name:formVal('name'),examDate:formVal('examDate'),color:formVal('color')||palette[0]};if(!obj.name)return;if(x)Object.assign(x,obj);else{let s={id:id(),...obj,createdAt:today()};db.subjects.push(s);activeSubject=s.id}closeModal();save();goto('subjects');toast(x?'Asignatura actualizada.':'Asignatura creada.')}else if(type==='topic'){let x=topic(formVal('tid')),obj={name:formVal('name'),subjectId:formVal('subjectId'),priority:Number(formVal('priority')),status:formVal('status')};if(!obj.name)return;if(x)Object.assign(x,obj);else{let t={id:id(),...obj,notes:'',createdAt:today()};db.topics.push(t);activeTopic=t.id}activeSubject=obj.subjectId;closeModal();save();goto('subjects');toast(x?'Tema actualizado.':'Tema creado.')}else if(type==='card'){let x=db.cards.find(c=>c.id===formVal('cid')),obj={topicId:formVal('topicId'),front:formVal('front'),back:formVal('back')};if(!obj.front||!obj.back)return;if(x)Object.assign(x,obj);else db.cards.push({id:id(),...obj,box:0,due:today(),reps:0,createdAt:today()});activeTopic=obj.topicId;closeModal();save();render();toast('Tarjeta guardada.')}else if(type==='task'){db.tasks.push({id:id(),title:formVal('title'),topicId:formVal('topicId'),due:formVal('due'),done:false});closeModal();save();render();toast('Tarea añadida.')}else if(type==='material'){let file=data.get('file'),btn=form.querySelector('[type=submit]');try{btn.disabled=true;btn.textContent='Procesando material…';let tx=formVal('text'),kind='Texto';if(file&&file.size){let extracted=await extractFile(file);tx=[tx,extracted].filter(Boolean).join('\n\n');kind=file.name.split('.').pop().toUpperCase()}if(!tx.trim())throw new Error('Añade texto o selecciona un archivo válido.');if(tx.length>180000){tx=tx.slice(0,180000);toast('El texto se ha limitado a 180.000 caracteres por documento.')}let m={id:id(),title:formVal('title')||file?.name||'Documento',topicId:formVal('topicId'),text:tx,kind,date:today()};db.materials.push(m);activeTopic=m.topicId;if(!save()){db.materials.pop();throw new Error('El almacenamiento está lleno; prueba con un documento más pequeño.')}closeModal();goto('material');toast('Material añadido correctamente.')}catch(e){toast(e.message||'No se pudo importar el archivo.',true)}finally{btn.disabled=false;btn.textContent='Importar / guardar'}}}
function handleChange(e){if(e.target.dataset.taskCheck){let t=db.tasks.find(x=>x.id===e.target.dataset.taskCheck);if(t){t.done=e.target.checked;save();render()}return}if(e.target.dataset.topicStatus){let t=topic(e.target.dataset.topicStatus);if(t){t.status=e.target.value;save();render()}return}if(e.target.id==='review-filter'){reviewFilter=e.target.value;reviewFlipped=false;render()}if(e.target.id==='quiz-filter'){quizFilter=e.target.value;quiz=null;render()}if(e.target.id==='backup-input'){let file=e.target.files?.[0];if(!file)return;file.text().then(txt=>{let obj=JSON.parse(txt);if(!Array.isArray(obj.subjects)||!Array.isArray(obj.topics)||!Array.isArray(obj.cards)||!Array.isArray(obj.materials)||!Array.isArray(obj.tasks))throw new Error('La copia no contiene los datos necesarios.');if(confirm('¿Restaurar esta copia? Se reemplazarán todos los datos actuales.')){db={...blank(),...obj};if(!save())throw new Error('No se pudo guardar la copia; podría ser demasiado grande.');securitySeed();activeSubject=activeTopic=null;closeModal();goto('home');toast('Copia restaurada.')}}).catch(err=>toast('No se pudo restaurar: '+err.message,true))}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){goto(nav.dataset.nav);return}const a=e.target.closest('[data-action]');if(a){e.preventDefault();handleAction(a);return}if(e.target.matches('[data-overlay]'))closeModal()});
document.addEventListener('submit',e=>{const f=e.target.closest('form[data-form]');if(f){e.preventDefault();handleForm(f)}});
document.addEventListener('change',handleChange);
document.addEventListener('input',e=>{if(e.target.id==='topic-notes'){let t=topic(e.target.dataset.note);if(!t)return;t.notes=e.target.value;const st=document.getElementById('note-status');if(st)st.textContent='Guardando…';clearTimeout(noteSaveTimer);noteSaveTimer=setTimeout(()=>{save();if(st)st.textContent='Guardado automáticamente'},420)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Enter'&&e.target.closest('.flashcard')){e.preventDefault();reviewFlipped=!reviewFlipped;render()}});
